<?php
namespace App\Http\Middleware;use App\Models\AdminAuditLog;use Closure;use Illuminate\Http\Request;use Symfony\Component\HttpFoundation\Response;
class RecordAdminAction{public function handle(Request $request,Closure $next):Response{$response=$next($request);if(!in_array($request->method(),['GET','HEAD','OPTIONS'],true)&&$response->getStatusCode()<400){$parameters=$request->route()?->parameters()??[];$subject=collect($parameters)->first(fn($value)=>$value instanceof \Illuminate\Database\Eloquent\Model);AdminAuditLog::create(['actor_id'=>$request->user()?->id,'action'=>strtolower($request->method()).' '.$request->route()?->getName()??$request->path(),'method'=>$request->method(),'path'=>$request->path(),'subject_type'=>$subject?->getMorphClass(),'subject_id'=>$subject?->getKey(),'metadata'=>collect($request->except(['password','password_confirmation','photo','image']))->map(fn($v)=>is_scalar($v)||is_null($v)?$v:'[complex]')->all(),'ip_address'=>$request->ip()]);}return $response;}}
